INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('giyeok', 'ㄱ', 'giyeok', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㄱ (기역)","explanation":"한글 자음 첫 번째 글자. 혀뿌리가 목구멍을 막는 모양을 본떠 만든 글자입니다."},"en":{"word":"giyeok (ㄱ)","explanation":"The first consonant of the Korean alphabet. Pronounced like ''g'' or ''k''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('nieun', 'ㄴ', 'nieun', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㄴ (니은)","explanation":"한글 자음 두 번째 글자. 혀끝이 윗잇몸에 닿는 모양을 본떠 만든 글자입니다."},"en":{"word":"nieun (ㄴ)","explanation":"The second consonant. Pronounced like ''n''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('digeut', 'ㄷ', 'digeut', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㄷ (디귿)","explanation":"한글 자음 세 번째 글자. ㄴ에 획을 더하여 만든 글자입니다."},"en":{"word":"digeut (ㄷ)","explanation":"The third consonant. Pronounced like ''d'' or ''t''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('rieul', 'ㄹ', 'rieul', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㄹ (리을)","explanation":"한글 자음 네 번째 글자. 영어의 ''r''과 ''l'' 사이의 소리입니다."},"en":{"word":"rieul (ㄹ)","explanation":"The fourth consonant. Pronounced between ''r'' and ''l''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('mieum', 'ㅁ', 'mieum', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅁ (미음)","explanation":"한글 자음 다섯 번째 글자. 입술 모양을 본떠 만든 글자입니다."},"en":{"word":"mieum (ㅁ)","explanation":"The fifth consonant. Pronounced like ''m''. Shaped like closed lips."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('bieup', 'ㅂ', 'bieup', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅂ (비읍)","explanation":"한글 자음 여섯 번째 글자. ㅁ에 획을 더하여 만든 글자입니다."},"en":{"word":"bieup (ㅂ)","explanation":"The sixth consonant. Pronounced like ''b'' or ''p''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('siot', 'ㅅ', 'siot', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅅ (시옷)","explanation":"한글 자음 일곱 번째 글자. 이빨 모양을 본떠 만든 글자입니다."},"en":{"word":"siot (ㅅ)","explanation":"The seventh consonant. Pronounced like ''s''. Shaped like teeth."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('ieung', 'ㅇ', 'ieung', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅇ (이응)","explanation":"한글 자음 여덟 번째 글자. 초성에서는 소리가 없고, 종성에서는 ng 소리가 납니다."},"en":{"word":"ieung (ㅇ)","explanation":"The eighth consonant. Silent initially, ''ng'' sound finally."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('jieut', 'ㅈ', 'jieut', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅈ (지읒)","explanation":"한글 자음 아홉 번째 글자. ㅅ에 획을 더하여 만든 글자입니다."},"en":{"word":"jieut (ㅈ)","explanation":"The ninth consonant. Pronounced like ''j''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('chieut', 'ㅊ', 'chieut', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅊ (치읓)","explanation":"한글 자음 열 번째 글자. ㅈ의 거센소리(격음)입니다."},"en":{"word":"chieut (ㅊ)","explanation":"The tenth consonant. Aspirated ''ch'' sound."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('kieuk', 'ㅋ', 'kieuk', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅋ (키읔)","explanation":"한글 자음 열한 번째 글자. ㄱ의 거센소리(격음)입니다."},"en":{"word":"kieuk (ㅋ)","explanation":"The eleventh consonant. Aspirated ''k'' sound."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('tieut', 'ㅌ', 'tieut', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅌ (티읕)","explanation":"한글 자음 열두 번째 글자. ㄷ의 거센소리(격음)입니다."},"en":{"word":"tieut (ㅌ)","explanation":"The twelfth consonant. Aspirated ''t'' sound."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('pieup', 'ㅍ', 'pieup', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅍ (피읖)","explanation":"한글 자음 열세 번째 글자. ㅂ의 거센소리(격음)입니다."},"en":{"word":"pieup (ㅍ)","explanation":"The thirteenth consonant. Aspirated ''p'' sound."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('hieut', 'ㅎ', 'hieut', 'noun', 'consonants', 'beginner', 'common', '["alphabet","consonant"]', '{"ko":{"word":"ㅎ (히읗)","explanation":"한글 자음 마지막 글자. 목구멍에서 나오는 거친 숨소리를 나타냅니다."},"en":{"word":"hieut (ㅎ)","explanation":"The fourteenth and last consonant. Pronounced like ''h''."}}');

