-- Basic Vowel Entries (10)
-- ============================================
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('a-vowel', 'ㅏ', 'a', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅏ (아)","explanation":"한글 기본 모음 첫 번째 글자. 입을 크게 벌리고 내는 밝은 소리입니다."},"en":{"word":"a (ㅏ)","explanation":"First basic vowel. Pronounced ''a'' as in ''father''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('ya-vowel', 'ㅑ', 'ya', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅑ (야)","explanation":"ㅏ에서 획을 하나 더한 것으로, ''y'' 소리가 앞에 붙습니다."},"en":{"word":"ya (ㅑ)","explanation":"Second basic vowel. Pronounced ''ya'' as in ''yacht''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('eo-vowel', 'ㅓ', 'eo', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅓ (어)","explanation":"입을 조금 벌리고 내는 어두운 소리입니다. 음성 모음에 해당합니다."},"en":{"word":"eo (ㅓ)","explanation":"Third basic vowel. Pronounced like ''u'' in ''cup''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('yeo-vowel', 'ㅕ', 'yeo', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅕ (여)","explanation":"ㅓ에서 획을 하나 더한 것으로, ''y'' 소리가 앞에 붙습니다."},"en":{"word":"yeo (ㅕ)","explanation":"Fourth basic vowel. Pronounced ''yuh''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('o-vowel', 'ㅗ', 'o', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅗ (오)","explanation":"입술을 둥글게 오므리고 내는 소리입니다. 양성 모음에 해당합니다."},"en":{"word":"o (ㅗ)","explanation":"Fifth basic vowel. Pronounced ''oh'' as in ''go''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('yo-vowel', 'ㅛ', 'yo', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅛ (요)","explanation":"ㅗ에서 획을 하나 더한 것으로, ''y'' 소리가 앞에 붙습니다."},"en":{"word":"yo (ㅛ)","explanation":"Sixth basic vowel. Pronounced ''yo'' as in ''yoga''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('u-vowel', 'ㅜ', 'u', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅜ (우)","explanation":"입술을 둥글게 오므리고 앞으로 내밀어 내는 소리입니다."},"en":{"word":"u (ㅜ)","explanation":"Seventh basic vowel. Pronounced ''oo'' as in ''moon''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('yu-vowel', 'ㅠ', 'yu', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅠ (유)","explanation":"ㅜ에서 획을 하나 더한 것으로, ''y'' 소리가 앞에 붙습니다."},"en":{"word":"yu (ㅠ)","explanation":"Eighth basic vowel. Pronounced ''yoo''. ㅠㅠ means crying online."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('eu-vowel', 'ㅡ', 'eu', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅡ (으)","explanation":"입을 옆으로 벌리고 내는 소리로, 영어에 없는 독특한 한국어 모음입니다."},"en":{"word":"eu (ㅡ)","explanation":"Ninth basic vowel. No English equivalent. Spread lips and say ''oo''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('i-vowel', 'ㅣ', 'i', 'noun', 'vowels-basic', 'beginner', 'common', '["alphabet","vowel"]', '{"ko":{"word":"ㅣ (이)","explanation":"한글 기본 모음 마지막 글자. 훈민정음에서 사람을 상징합니다."},"en":{"word":"i (ㅣ)","explanation":"Tenth and last basic vowel. Pronounced ''ee'' as in ''see''."}}');

