-- Compound Vowel Entries (11)
-- ============================================
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('ae-vowel', 'ㅐ', 'ae', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅐ (애)","explanation":"ㅏ와 ㅣ가 합쳐진 복합 모음입니다. 현대 한국어에서는 ㅔ와 거의 같은 소리입니다."},"en":{"word":"ae (ㅐ)","explanation":"Compound vowel (ㅏ+ㅣ). Pronounced like ''e'' in ''bed''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('yae-vowel', 'ㅒ', 'yae', 'noun', 'vowels-compound', 'beginner', 'rare', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅒ (얘)","explanation":"ㅑ와 ㅣ가 합쳐진 복합 모음입니다. 사용 빈도가 낮습니다."},"en":{"word":"yae (ㅒ)","explanation":"Compound vowel (ㅑ+ㅣ). Pronounced ''yeh''. Rarely used."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('e-vowel', 'ㅔ', 'e', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅔ (에)","explanation":"ㅓ와 ㅣ가 합쳐진 복합 모음입니다. ㅐ와 거의 같은 소리입니다."},"en":{"word":"e (ㅔ)","explanation":"Compound vowel (ㅓ+ㅣ). Pronounced like ''e'' in ''bed''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('ye-vowel', 'ㅖ', 'ye', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅖ (예)","explanation":"ㅕ와 ㅣ가 합쳐진 복합 모음입니다. ''예'' (yes)에서 자주 쓰입니다."},"en":{"word":"ye (ㅖ)","explanation":"Compound vowel (ㅕ+ㅣ). Pronounced ''yeh''. Used in ''예'' (yes)."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('wa-vowel', 'ㅘ', 'wa', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅘ (와)","explanation":"ㅗ와 ㅏ가 합쳐진 복합 모음입니다."},"en":{"word":"wa (ㅘ)","explanation":"Compound vowel (ㅗ+ㅏ). Pronounced ''wa'' as in ''wand''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('wae-vowel', 'ㅙ', 'wae', 'noun', 'vowels-compound', 'intermediate', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅙ (왜)","explanation":"ㅗ와 ㅐ가 합쳐진 복합 모음입니다. ''왜'' (why)에서 자주 쓰입니다."},"en":{"word":"wae (ㅙ)","explanation":"Compound vowel (ㅗ+ㅐ). Pronounced ''weh''. Used in ''왜'' (why)."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('oe-vowel', 'ㅚ', 'oe', 'noun', 'vowels-compound', 'intermediate', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅚ (외)","explanation":"ㅗ와 ㅣ가 합쳐진 복합 모음입니다. 현대에는 [we]로 발음됩니다."},"en":{"word":"oe (ㅚ)","explanation":"Compound vowel (ㅗ+ㅣ). Now pronounced [we] in modern Korean."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('wo-vowel', 'ㅝ', 'wo', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅝ (워)","explanation":"ㅜ와 ㅓ가 합쳐진 복합 모음입니다."},"en":{"word":"wo (ㅝ)","explanation":"Compound vowel (ㅜ+ㅓ). Pronounced ''wuh''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('we-vowel', 'ㅞ', 'we', 'noun', 'vowels-compound', 'intermediate', 'rare', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅞ (웨)","explanation":"ㅜ와 ㅔ가 합쳐진 복합 모음입니다. 주로 외래어에 쓰입니다."},"en":{"word":"we (ㅞ)","explanation":"Compound vowel (ㅜ+ㅔ). Pronounced ''weh''. Mainly in loanwords."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('wi-vowel', 'ㅟ', 'wi', 'noun', 'vowels-compound', 'beginner', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅟ (위)","explanation":"ㅜ와 ㅣ가 합쳐진 복합 모음입니다."},"en":{"word":"wi (ㅟ)","explanation":"Compound vowel (ㅜ+ㅣ). Pronounced ''wee''."}}');
INSERT OR REPLACE INTO entries (id, korean, romanization, part_of_speech, category_id, difficulty, frequency, tags, translations) VALUES ('ui-vowel', 'ㅢ', 'ui', 'noun', 'vowels-compound', 'intermediate', 'common', '["alphabet","vowel","compound"]', '{"ko":{"word":"ㅢ (의)","explanation":"ㅡ와 ㅣ가 합쳐진 복합 모음입니다. 위치에 따라 발음이 3가지로 변합니다."},"en":{"word":"ui (ㅢ)","explanation":"Compound vowel (ㅡ+ㅣ). Has 3 pronunciations depending on position."}}');
